-- =============================================================================
-- 535 — LE CAHIER D'EXERCICES DE 1RE (partie 23)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/1re/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 535 --niveau 1re --fichiers histoire-geo.n1,histoire-geo.n2 --suffixe 23 > supabase/contenu/535_exercices_1re_23.sql
--
-- 66 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   histoire-geo.n1         33 exercices · 11 chapitres
--   histoire-geo.n2         33 exercices · 11 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('7f5f03d8-7ec1-59d5-b5ae-396fd0e9847a'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Dix ans pour changer une nation","competence":"se-reperer-temps","situation":"Camille prépare une affiche pour son cours d’histoire : elle veut montrer en un coup d’œil comment la France change de régime entre 1789 et 1799. Elle a tracé une frise et te demande de la relire avec elle.","documents":[{"id":"frise","type":"frise","titre":"La Révolution, de 1789 à 1799","source":"Frise réalisée pour l’exercice.","debut":1789,"fin":1799,"pas":1,"periodes":[{"id":"z1","debut":1791,"fin":1792,"nom":"Monarchie constitutionnelle","teinte":"ambre"},{"id":"z2","debut":1793,"fin":1794,"nom":"Terreur","teinte":"corail"},{"id":"z3","debut":1795,"fin":1799,"nom":"Directoire","teinte":"turquoise"}],"evenements":[{"id":"z4","date":1789,"nom":"Droits de l’homme"},{"id":"z5","date":1791,"nom":"Fuite à Varennes"},{"id":"z6","date":1792,"nom":"République"},{"id":"z7","date":1793,"nom":"Louis XVI exécuté"},{"id":"z8","date":1794,"nom":"Chute de Robespierre"}]}],"questions":[{"enonce":"Touche l’événement qui se produit en 1791.","aide":"Repère l’année 1791 sur la ligne graduée, puis cherche le repère placé à cet endroit.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent la Déclaration des droits de l’homme de la chute de Robespierre ?","aide":"Lis les deux années sur la frise, puis fais la soustraction.","type":"nombre","unite":"ans"},{"enonce":"Quel régime la frise place-t-elle juste après la Terreur ?","aide":"Regarde les périodes dessinées après 1794.","type":"choix","options":[{"id":"a","texte":"Le Directoire"},{"id":"b","texte":"Le Consulat"},{"id":"c","texte":"La monarchie constitutionnelle"},{"id":"d","texte":"L’Empire"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z5"]},"explication":"C’est **la fuite à Varennes** (juin 1791) : le roi tente de quitter le pays et la confiance avec l’Assemblée est ruinée."},{"cle":{"type":"nombre","valeur":5,"tolerance":0},"affichage":"5 ans","explication":"Les droits de l’homme datent de 1789, la chute de Robespierre de 1794 : 1794 − 1789 = **5 ans**."},{"cle":{"type":"choix","ids":["a"]},"explication":"Après la Terreur (1793-1794) vient **le Directoire**, de 1795 à 1799."}]$ex$::jsonb),
  ('7f5f03d8-7ec1-59d5-b5ae-396fd0e9847a'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Qui a le droit de voter en 1791 ?","competence":"analyser-document","situation":"Dans le bourg imaginaire de Saint-Aubin, le maire affiche la liste des habitants avant les élections de 1791. Pour la Constitution, sont citoyens actifs (donc électeurs) les Français de sexe masculin, âgés de 25 ans au moins, qui paient un impôt d’au moins trois journées de travail. Paul compare cette règle aux grands principes de 1789.","documents":[{"id":"ddh","type":"texte","genre":"source","titre":"Déclaration des droits de l’homme et du citoyen (26 août 1789)","source":"Extraits des articles 1 et 3.","blocs":["Article 1. Les hommes naissent et demeurent libres et égaux en droits. Les distinctions sociales ne peuvent être fondées que sur l’utilité commune.","Article 3. Le principe de toute Souveraineté réside essentiellement dans la Nation. Nul corps, nul individu ne peut exercer d’autorité qui n’en émane expressément."]},{"id":"bourg","type":"tableau","titre":"Cinq habitants de Saint-Aubin en 1791","source":"Habitants imaginés pour l’exercice.","colonnes":["Habitant","Sexe","Âge","Impôt (journées de travail)"],"lignes":[["Marie Garnier","Femme",40,4],["Joseph Lenoir","Homme",52,5],["Pierre Dubois","Homme",30,1],["Louis Faure","Homme",24,6],["Antoine Roux","Homme",45,3]],"enteteLignes":false}],"questions":[{"enonce":"Touche le mot qui désigne, dans l’article 3, celui qui détient la souveraineté.","aide":"Cherche le mot qui suit « réside essentiellement dans la ».","type":"zone","document":"ddh","multiple":false},{"enonce":"Touche le nom des habitants qui sont citoyens actifs et peuvent voter en 1791.","aide":"Vérifie les trois conditions pour chaque personne : sexe, âge, impôt.","type":"zone","document":"bourg","multiple":true},{"enonce":"Combien de journées de travail d’impôt manque-t-il à Pierre Dubois pour devenir citoyen actif ?","aide":"Il lui faut au moins trois journées de travail d’impôt.","type":"nombre","unite":"journées"},{"enonce":"Que montre la comparaison entre l’article 1 de 1789 et la liste de Saint-Aubin ?","aide":"Relis la phrase « libres et égaux en droits » puis regarde qui vote vraiment.","type":"choix","options":[{"id":"a","texte":"L’égalité en droits est proclamée, mais le droit de vote reste réservé à une partie des hommes"},{"id":"b","texte":"Le roi garde seul la souveraineté, malgré ce que dit l’article 3 de la Déclaration"},{"id":"c","texte":"Les femmes obtiennent le droit de vote, mais tous les hommes du bourg le perdent"},{"id":"d","texte":"Tous les habitants du bourg votent à égalité, sans condition d’âge ni d’impôt payé"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m35"]},"explication":"La souveraineté appartient à **la Nation** : ce n’est plus le roi qui la détient, c’est le corps des citoyens."},{"cle":{"type":"zone","ids":["r1c0","r4c0"]},"explication":"Seuls **Joseph Lenoir** et **Antoine Roux** réunissent les trois conditions. Marie est une femme, Pierre paie trop peu d’impôt (1 journée), Louis n’a que 24 ans."},{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2 journées","explication":"Pierre paie 1 journée, il en faut 3 : 3 − 1 = **2** journées de moins que ce qu’il faudrait."},{"cle":{"type":"choix","ids":["a"]},"explication":"L’égalité **proclamée** n’est pas encore l’égalité **politique** : trois habitants sur cinq ne votent pas. C’est la tension qui traverse toute la décennie."}]$ex$::jsonb),
  ('7f5f03d8-7ec1-59d5-b5ae-396fd0e9847a'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Du roi en fuite à la chute de Robespierre","competence":"raisonner","situation":"Rouen, fin juin 1791. Une marchande écrit à sa sœur pour lui raconter la nouvelle qui bouleverse le pays. Toi, tu relies cette lettre à la frise de la décennie pour comprendre l’enchaînement qui mène du roi à la République, puis à la Terreur.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Lettre d’une marchande de Rouen (juin 1791)","source":"Lettre imaginée pour l’exercice.","blocs":["Ma chère Jeanne, tout Rouen ne parle que de la fuite du roi. Il a quitté Paris de nuit avec sa famille ; on l’a reconnu et arrêté à Varennes, tout près de la frontière.","Beaucoup se demandent s’il allait rejoindre les armées étrangères pour défaire ce que l’Assemblée a bâti. Comment lui faire encore confiance ?"]},{"id":"frise","type":"frise","titre":"Les régimes de 1789 à 1799","source":"Frise réalisée pour l’exercice.","debut":1789,"fin":1799,"pas":1,"periodes":[{"id":"z1","debut":1791,"fin":1792,"nom":"Monarchie constitutionnelle","teinte":"ambre"},{"id":"z2","debut":1795,"fin":1799,"nom":"Directoire","teinte":"turquoise"}],"evenements":[{"id":"z3","date":1791,"nom":"Fuite à Varennes"},{"id":"z4","date":1792,"nom":"République"},{"id":"z5","date":1793,"nom":"Louis XVI exécuté"},{"id":"z6","date":1794,"nom":"Chute de Robespierre"}]}],"questions":[{"enonce":"Touche le nom de la ville où le roi est arrêté.","aide":"Cherche un nom de lieu dans le premier paragraphe.","type":"zone","document":"lettre","multiple":false},{"enonce":"Pourquoi cette fuite ruine-t-elle la confiance entre le roi et l’Assemblée ?","aide":"Relis la dernière phrase de la lettre : que soupçonne-t-on ?","type":"choix","options":[{"id":"a","texte":"Elle oblige l’Assemblée à fuir à son tour hors de Paris"},{"id":"b","texte":"Elle prouve que le roi a perdu toute autorité sur son armée"},{"id":"c","texte":"Elle laisse croire que le roi veut s’appuyer sur les ennemis de la Révolution"},{"id":"d","texte":"Elle montre que l’Assemblée voulait déjà supprimer la monarchie"}],"multiple":false},{"enonce":"Remets dans l’ordre les étapes qui mènent de la fuite du roi à la République.","aide":"La guerre précède la chute de la royauté, et la République ne vient qu’ensuite.","type":"ordre","items":[{"id":"a","texte":"Journée du 10 août 1792 : la royauté tombe"},{"id":"b","texte":"Fuite et arrestation du roi à Varennes (juin 1791)"},{"id":"c","texte":"Proclamation de la République (22 septembre 1792)"},{"id":"d","texte":"Déclaration de guerre (avril 1792)"}]},{"enonce":"Le Directoire (1795-1799) est censitaire et instable. Que montre-t-il en 1799 ?","aide":"Pense à ce que laissent la Terreur puis un régime instable : un régime durable est-il trouvé ?","type":"choix","options":[{"id":"a","texte":"La France n’a conservé aucun acquis de la Révolution de 1789"},{"id":"b","texte":"La question reste ouverte : comment fonder un régime stable sur la souveraineté du peuple ?"},{"id":"c","texte":"La question est réglée : le régime est stable et tous les citoyens votent"},{"id":"d","texte":"La Révolution a rétabli l’ancienne société d’ordres avec un roi absolu"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m29"]},"explication":"Le roi est arrêté à **Varennes**, près de la frontière : on le soupçonne de vouloir rejoindre les ennemis de la Révolution."},{"cle":{"type":"choix","ids":["c"]},"explication":"Un roi qui part de nuit vers la frontière semble rejoindre les armées étrangères : la **confiance est rompue**, et la monarchie constitutionnelle ne s’en remet pas."},{"cle":{"type":"ordre","ids":["b","d","a","c"]},"explication":"Varennes (juin 1791), puis **la guerre** (avril 1792), puis **le 10 août 1792** qui emporte la royauté, enfin **la République** le 22 septembre 1792."},{"cle":{"type":"choix","ids":["b"]},"explication":"Après dix ans, la France a gagné l’égalité civile mais pas de régime durable : **cette question ouverte** prépare l’arrivée de Bonaparte."}]$ex$::jsonb),
  ('2750d3a8-82ce-5c4e-a878-7ec3e3c9b7dd'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Les masses de granit du Consulat","competence":"lire-tableau","situation":"Hugo a trouvé dans son manuel la liste des grandes institutions créées par Bonaparte quand il gouverne la France, après 1799. Il doit les dater et comprendre ce que chacune apporte.","documents":[{"id":"inst","type":"tableau","titre":"Les institutions de Bonaparte","source":"Dates tirées du cours.","colonnes":["Institution","Année"],"lignes":[["Les préfets",1800],["La Banque de France",1800],["Le Concordat",1801],["Les lycées et la Légion d’honneur",1802],["Le franc germinal",1803],["Le Code civil",1804]],"enteteLignes":false}],"questions":[{"enonce":"Touche l’année de l’accord avec le pape qui rétablit la paix religieuse.","aide":"Cherche l’accord conclu avec le pape.","type":"zone","document":"inst","multiple":false},{"enonce":"Combien d’années séparent la création des préfets de celle du Code civil ?","aide":"Lis les deux années dans le tableau, puis soustrais.","type":"nombre","unite":"ans"},{"enonce":"Associe chaque institution à ce qu’elle consacre.","aide":"Chaque institution touche un domaine : religion, droit, administration, argent.","type":"association","gauche":[{"id":"g0","texte":"Le Concordat"},{"id":"g1","texte":"Le Code civil"},{"id":"g2","texte":"Les préfets"},{"id":"g3","texte":"La Banque de France"}],"droite":[{"id":"d0","texte":"L’égalité devant la loi et la propriété"},{"id":"d1","texte":"La paix religieuse sous contrôle de l’État"},{"id":"d2","texte":"La stabilité de la monnaie"},{"id":"d3","texte":"La centralisation du pays"}]}]}$ex$::jsonb,
