  ('2750d3a8-82ce-5c4e-a878-7ec3e3c9b7dd'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Plébiscite : voter pour dire oui","competence":"analyser-document","situation":"Pour son exposé, Inès doit répondre à une question : Napoléon a-t-il sauvé la Révolution ou l’a-t-il confisquée ? Elle dispose des résultats de trois plébiscites et de deux lectures opposées.","documents":[{"id":"plebi","type":"tableau","titre":"Les trois grands plébiscites","source":"Résultats officiels, chiffres arrondis.","colonnes":["Année","Question posée","Oui (millions)","Non (milliers)"],"lignes":[[1799,"Constitution de l’an VIII","3,0","1,6"],[1802,"Consulat à vie","3,6","8,4"],[1804,"Empire héréditaire","3,6","2,6"]],"enteteLignes":false},{"id":"lectures","type":"texte","genre":"article","titre":"Deux lectures de Napoléon","source":"Textes écrits pour l’exercice.","blocs":["Lecture A. En gravant l’égalité civile, la propriété et l’état civil laïque dans le Code civil, Bonaparte a consolidé les acquis de 1789.","Lecture B. En supprimant les libertés politiques et en gouvernant par plébiscite, il a inventé un pouvoir personnel appuyé sur la police et la censure."]}],"questions":[{"enonce":"Touche l’année du plébiscite qui fait de Bonaparte consul à vie.","aide":"Cherche la ligne qui parle du consulat à vie.","type":"zone","document":"plebi","multiple":false},{"enonce":"Combien de millions de « oui » de plus y a-t-il en 1802 qu’en 1799 ?","aide":"Compare les deux valeurs de la colonne « Oui ».","type":"nombre","unite":"millions"},{"enonce":"Que montre le tableau, sur le rôle de ces votes ?","aide":"Regarde l’écart entre les « oui » et les « non » : un vrai choix donnerait-il de tels résultats ?","type":"choix","options":[{"id":"a","texte":"Le vote est supprimé et remplacé par la décision de l’armée"},{"id":"b","texte":"On vote pour approuver un régime déjà décidé, sans véritable choix ni débat"},{"id":"c","texte":"Les Français rejettent massivement chacun des trois régimes proposés"},{"id":"d","texte":"Seuls les plus riches ont le droit de voter lors de ces consultations"}],"multiple":false},{"enonce":"Touche, dans la lecture B, le mot qui désigne le vote par lequel Bonaparte fait approuver ses régimes.","aide":"Le mot est précédé de « gouvernant par ».","type":"zone","document":"lectures","multiple":false},{"enonce":"Classe chaque élément : acquis de 1789 conservés, ou liberté politique suspendue ?","aide":"Le Code civil conserve les droits civils ; la police et la censure touchent les libertés politiques.","type":"categories","categories":[{"id":"c0","texte":"Acquis conservé"},{"id":"c1","texte":"Liberté suspendue"}],"items":[{"id":"i0","texte":"Des assemblées sans réel pouvoir"},{"id":"i1","texte":"L’état civil laïque"},{"id":"i2","texte":"La liberté de la presse, soumise à la censure"},{"id":"i3","texte":"La propriété garantie par le Code civil"},{"id":"i4","texte":"L’égalité devant la loi"}]}]}$ex$::jsonb,
