   $ex${"titre":"Pourquoi l’empereur concède","competence":"raisonner","situation":"En 1868, un conseiller imaginaire écrit une note à l’empereur. Mathis la lit avec une frise pour comprendre pourquoi un régime autoritaire accorde des libertés… et pourquoi cela ne le sauve pas.","documents":[{"id":"frise","type":"frise","titre":"Le Second Empire","source":"Frise réalisée pour l’exercice.","debut":1850,"fin":1872,"pas":2,"periodes":[{"id":"z1","debut":1852,"fin":1860,"nom":"Empire autoritaire","teinte":"ambre"},{"id":"z2","debut":1860,"fin":1870,"nom":"Empire libéral","teinte":"turquoise"}],"evenements":[{"id":"z3","date":1852,"nom":"Empire rétabli"},{"id":"z4","date":1857,"nom":"Les « Cinq »"},{"id":"z5","date":1864,"nom":"Loi Ollivier"},{"id":"z6","date":1868,"nom":"Presse libre"},{"id":"z7","date":1870,"nom":"Sedan"}]},{"id":"note","type":"texte","genre":"lettre","titre":"Note d’un conseiller (1868)","source":"Note imaginée pour l’exercice.","blocs":["Sire, aux élections de 1863, l’opposition a rassemblé près de deux millions de voix, et elle progresse dans les grandes villes.","Si nous ne lâchons pas un peu de liberté — presse, réunion —, nous risquons de tout perdre. Mieux vaut concéder que subir."]}],"questions":[{"enonce":"Touche la période où l’empereur accorde peu à peu des libertés.","aide":"Cherche la période qui commence en 1860.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent l’élection des « Cinq » de la liberté de la presse ?","aide":"Lis les deux repères sur la frise.","type":"nombre","unite":"ans"},{"enonce":"Touche, dans la note, le mot qui désigne les adversaires du régime dont les voix progressent.","aide":"Il s’agit de ceux qui s’opposent à l’empereur.","type":"zone","document":"note","multiple":false},{"enonce":"Pourquoi l’empereur choisit-il de concéder des libertés ?","aide":"Relis la dernière phrase de la note.","type":"choix","options":[{"id":"a","texte":"Le Corps législatif a voté sa destitution à une large majorité"},{"id":"b","texte":"Il est affaibli par la montée de l’opposition et préfère céder que tout perdre"},{"id":"c","texte":"Une armée étrangère l’y oblige par la force dès l’année 1868"},{"id":"d","texte":"Il est devenu républicain et veut abolir lui-même le régime impérial"}],"multiple":false},{"enonce":"Que se passe-t-il en 1870 ?","aide":"Regarde le dernier repère de la frise.","type":"choix","options":[{"id":"a","texte":"L’empereur abdique volontairement pour céder la place à son fils"},{"id":"b","texte":"Sedan emporte le régime, et la République est proclamée sans révolution"},{"id":"c","texte":"Le Corps législatif proclame l’Empire héréditaire dans toute la France"},{"id":"d","texte":"Un nouveau plébiscite supprime le suffrage universel masculin pour tous"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"C’est **l’Empire libéral** (1860-1870) : droit d’adresse, droit de grève, liberté de la presse…"},{"cle":{"type":"nombre","valeur":11,"tolerance":0},"affichage":"11 ans","explication":"1868 − 1857 = **11 ans** entre l’élection des « Cinq » et la liberté de la presse."},{"cle":{"type":"zone","ids":["m6"]},"explication":"Le mot est **opposition** : c’est sa progression qui inquiète le conseiller."},{"cle":{"type":"choix","ids":["b"]},"explication":"Affaibli par ses difficultés extérieures et par la montée de l’opposition, Napoléon III **concède pour garder le pouvoir**."},{"cle":{"type":"choix","ids":["b"]},"explication":"La capitulation de **Sedan** (2 septembre 1870) emporte le régime ; la République est proclamée le 4 septembre, sans révolution."}]$ex$::jsonb),
