   $ex${"titre":"Un réseau en étoile","competence":"lire-carte","situation":"Ambre étudie le chemin de fer du Second Empire. Elle regarde d’abord la forme du réseau sur une carte, puis la longueur des voies sur un graphique.","documents":[{"id":"carte","type":"carte","titre":"Les grandes lignes de chemin de fer (schéma)","source":"Schéma simplifié pour l’exercice.","fond":"france","lieux":[{"id":"z1","lieu":"paris","symbole":"carre","nom":"Paris"},{"id":"z2","lieu":"lille","symbole":"point","nom":"Lille"},{"id":"z3","lieu":"strasbourg","symbole":"point","nom":"Strasbourg"},{"id":"z4","lieu":"lyon","symbole":"point","nom":"Lyon"},{"id":"z5","lieu":"marseille","symbole":"point","nom":"Marseille"},{"id":"z6","lieu":"bordeaux","symbole":"point","nom":"Bordeaux"},{"id":"z7","lieu":"nantes","symbole":"point","nom":"Nantes"}],"traits":[{"id":"z8","points":["paris","lille"],"style":"ligne","teinte":"encre"},{"id":"z9","points":["paris","strasbourg"],"style":"ligne","teinte":"encre"},{"id":"z10","points":["paris","lyon","marseille"],"style":"ligne","teinte":"encre"},{"id":"z11","points":["paris","bordeaux"],"style":"ligne","teinte":"encre"},{"id":"z12","points":["paris","nantes"],"style":"ligne","teinte":"encre"}]},{"id":"km","type":"graphique","forme":"barres","titre":"Longueur du réseau ferré français","source":"Chiffres arrondis.","categories":["1851","1870"],"series":[{"nom":"Kilomètres","valeurs":[3000,17000],"teinte":"violet"}],"axeY":{"titre":"Longueur","unite":"en km","min":0,"max":18000,"pas":3000},"valeurs":false}],"questions":[{"enonce":"Touche la ville vers laquelle convergent toutes les lignes.","aide":"Toutes les lignes partent du même point, comme les branches d’une étoile.","type":"zone","document":"carte","multiple":false},{"enonce":"Touche la ligne qui relie Paris à la Méditerranée.","aide":"Cherche le trait qui descend jusqu’à Marseille.","type":"zone","document":"carte","multiple":false},{"enonce":"De combien de kilomètres le réseau s’allonge-t-il entre 1851 et 1870 ?","aide":"Lis les deux barres et soustrais.","type":"nombre","unite":"km"},{"enonce":"Par combien le réseau est-il environ multiplié entre 1851 et 1870 (arrondi à l’unité) ?","aide":"Divise la longueur de 1870 par celle de 1851.","type":"nombre"}]}$ex$::jsonb,
