  ('4ed653b6-ec49-5a1e-81b8-c16aa92185af'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Un maçon face aux travaux d’Haussmann","competence":"analyser-document","situation":"Paris, 1865. Le préfet Haussmann perce de grands boulevards. Un maçon imaginaire note ses comptes. Marius s’en sert pour mesurer ce que la ville gagne… et ce que les ouvriers perdent.","documents":[{"id":"journal","type":"texte","genre":"recit","titre":"Journal d’un maçon (1865)","source":"Journal imaginé pour l’exercice.","blocs":["Le préfet Haussmann a fait raser notre rue pour percer un boulevard large et aéré. On dit qu’il apporte l’eau, les égouts et les gares ; c’est vrai que la ville est plus saine.","Mais le prix du sol a flambé : mon loyer a doublé, et mes voisins partent s’installer toujours plus loin, vers la périphérie."]},{"id":"budget","type":"tableau","titre":"Les comptes du maçon","source":"Chiffres inventés pour l’exercice.","colonnes":["Poste","Montant"],"lignes":[["Salaire par jour travaillé","3 francs"],["Loyer annuel avant les travaux","150 francs"],["Loyer annuel après les travaux","300 francs"]],"enteteLignes":false}],"questions":[{"enonce":"Touche la case qui chiffre le loyer après les travaux.","aide":"Cherche la ligne qui parle de « après les travaux ».","type":"zone","document":"budget","multiple":false},{"enonce":"Par combien le loyer est-il multiplié après les travaux ?","aide":"Divise le loyer d’après par le loyer d’avant.","type":"nombre"},{"enonce":"Combien de journées de travail faut-il au maçon pour payer son loyer annuel après les travaux ?","aide":"Divise le loyer annuel par le salaire d’une journée.","type":"nombre","unite":"journées"},{"enonce":"Quel effet social des travaux le journal du maçon révèle-t-il ?","aide":"Relis la dernière phrase du journal.","type":"choix","options":[{"id":"a","texte":"Les loyers baissent grâce aux nouveaux boulevards"},{"id":"b","texte":"Le prix du sol chasse les ouvriers vers la périphérie"},{"id":"c","texte":"Les ouvriers deviennent propriétaires des nouveaux immeubles"},{"id":"d","texte":"Les ouvriers quittent Paris pour travailler dans les champs"}],"multiple":false},{"enonce":"Classe chaque élément : effet voulu par Haussmann, ou effet subi par les ouvriers ?","aide":"Ce que le préfet cherchait n’est pas ce que subissent les habitants modestes.","type":"categories","categories":[{"id":"c0","texte":"Effet voulu"},{"id":"c1","texte":"Effet subi"}],"items":[{"id":"i0","texte":"Un départ vers la périphérie"},{"id":"i1","texte":"Une ville plus aérée et plus salubre"},{"id":"i2","texte":"L’eau et les égouts installés"},{"id":"i3","texte":"Un loyer qui double"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c1"]},"explication":"Le loyer passe à **300 francs** par an."},{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2","explication":"300 ÷ 150 = **2** : le loyer double, comme le dit le journal."},{"cle":{"type":"nombre","valeur":100,"tolerance":0},"affichage":"100 journées","explication":"300 ÷ 3 = **100** journées de travail rien que pour le loyer."},{"cle":{"type":"choix","ids":["b"]},"explication":"Les travaux embellissent Paris, mais **le prix du sol augmente** : les ouvriers sont repoussés vers la périphérie."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0","i3":"c1"}},"explication":"Une ville **aérée et salubre** et l’**eau et les égouts** étaient voulus. Le **loyer qui double** et le **départ vers la périphérie** sont des effets subis."}]$ex$::jsonb),
  ('79a99844-12b9-5663-bf86-96f358f9fd99'::uuid, 1, 1, 5, 20, 3,
