  ('79a99844-12b9-5663-bf86-96f358f9fd99'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le carnet d’un cultivateur","competence":"analyser-document","situation":"En 1860, un cultivateur imaginaire tient son carnet. Il raconte comment sa ferme a changé depuis l’arrivée du train à la gare voisine. Elias y repère les signes d’un monde rural qui bouge.","documents":[{"id":"carnet","type":"texte","genre":"recit","titre":"Carnet d’un cultivateur (1860)","source":"Carnet imaginé pour l’exercice.","blocs":["Avant, nous cultivions du blé et des légumes pour nous nourrir. Sur 30 quintaux de blé, la famille en gardait 24 ; on vendait le reste à la foire.","Depuis que le train passe à la gare voisine, je vends ma betterave à la sucrerie et mon lait à la ville. Je laisse moins mes champs en jachère : avec des engrais, la terre se repose moins longtemps."]}],"questions":[{"enonce":"Touche le mot qui désigne ce qui permet de moins laisser la terre en jachère.","aide":"Cherche ce qu’on apporte au sol pour le rendre plus fertile.","type":"zone","document":"carnet","multiple":false},{"enonce":"Avant le train, quelle part du blé (en %) la famille vendait-elle à la foire ?","aide":"Calcule d’abord la quantité vendue : 30 − 24, puis divise par 30.","type":"nombre","unite":"%"},{"enonce":"Classe chaque production : polyculture vivrière ou production spécialisée pour la vente ?","aide":"Demande-toi si la récolte nourrit la famille ou part sur le marché.","type":"categories","categories":[{"id":"c0","texte":"Polyculture vivrière"},{"id":"c1","texte":"Production spécialisée"}],"items":[{"id":"i0","texte":"Du blé gardé pour le pain de la famille"},{"id":"i1","texte":"Des légumes du potager familial"},{"id":"i2","texte":"Le lait vendu à la ville"},{"id":"i3","texte":"La betterave vendue à la sucrerie"}]},{"enonce":"Que change le chemin de fer dans la vie du village ?","aide":"Relis les deux paragraphes : que fait le cultivateur de sa récolte, avant puis après le train ?","type":"choix","options":[{"id":"a","texte":"On produit de plus en plus pour vendre, et plus seulement pour se nourrir"},{"id":"b","texte":"Les paysans cessent d’utiliser des engrais"},{"id":"c","texte":"Le village devient totalement autonome et se ferme au marché"},{"id":"d","texte":"On cesse de cultiver la terre pour partir à la ville"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m59"]},"explication":"Ce sont les **engrais** : avec la rotation des cultures, ils remplacent peu à peu la jachère."},{"cle":{"type":"nombre","valeur":20,"tolerance":0},"affichage":"20 %","explication":"30 − 24 = 6 quintaux vendus ; 6 ÷ 30 = 0,2, soit **20 %** du blé."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c1"}},"explication":"Le blé de la famille et les légumes relèvent de la **polyculture vivrière**. La betterave et le lait, vendus au loin, sont des **productions spécialisées**."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le rail fait entrer **le marché dans le village** : on cesse de produire seulement pour se nourrir et on produit pour vendre."}]$ex$::jsonb),
  ('79a99844-12b9-5663-bf86-96f358f9fd99'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Un monde rural qui bouge et se vide","competence":"raisonner","situation":"Lina compare l’évolution de la population rurale et le récit d’un jeune saisonnier imaginaire pour comprendre comment le monde rural change sans s’effondrer.","documents":[{"id":"courbe","type":"graphique","forme":"courbe","titre":"Part de la population rurale","source":"Valeurs arrondies, ordre de grandeur.","categories":["1851","1861","1872"],"series":[{"nom":"Population rurale (%)","valeurs":[75,71,69],"teinte":"violet"}],"axeY":{"titre":"Part rurale","unite":"en %","min":60,"max":80,"pas":5},"axeX":{"titre":"Année"}},{"id":"recit","type":"texte","genre":"recit","titre":"Léon, saisonnier","source":"Récit imaginé pour l’exercice.","blocs":["Léon a dix-sept ans. Chaque hiver, quand il n’y a plus de travail aux champs, il part à Lyon travailler sur les chantiers.","Au printemps, il revient au village aider sa famille. À la ville, il a appris quelques mots de français et lit parfois le journal."]}],"questions":[{"enonce":"De combien de points la part de la population rurale baisse-t-elle entre 1851 et 1872 ?","aide":"Lis la valeur de 1851 et celle de 1872, puis soustrais.","type":"nombre","unite":"points"},{"enonce":"Que montre cette courbe ?","aide":"Regarde la pente de la courbe et sa valeur finale.","type":"choix","options":[{"id":"a","texte":"La population rurale disparaît presque en vingt ans"},{"id":"b","texte":"La part rurale baisse lentement mais reste très majoritaire"},{"id":"c","texte":"La part rurale augmente régulièrement chaque année"},{"id":"d","texte":"La ville dépasse déjà la campagne dès 1861"}],"multiple":false},{"enonce":"Touche, dans le récit, le mot qui désigne l’endroit où Léon trouve du travail l’hiver.","aide":"Cherche ce que Léon fait à Lyon.","type":"zone","document":"recit","multiple":false},{"enonce":"Quel type de départ le récit illustre-t-il ?","aide":"Léon revient-il au printemps ?","type":"choix","options":[{"id":"a","texte":"Un départ à l’étranger pour y fonder une colonie"},{"id":"b","texte":"Un exode rural définitif et massif"},{"id":"c","texte":"Un retour à la terre après une longue vie en ville"},{"id":"d","texte":"Une migration saisonnière, lente et souvent temporaire"}],"multiple":false},{"enonce":"Associe chaque vecteur d’ouverture à ce qu’il diffuse dans les campagnes.","aide":"Pense à ce que chacun apporte au village : la langue, l’armée, les nouvelles.","type":"association","gauche":[{"id":"g0","texte":"L’école"},{"id":"g1","texte":"Le service militaire"},{"id":"g2","texte":"La presse et le colportage"}],"droite":[{"id":"d0","texte":"L’appartenance nationale"},{"id":"d1","texte":"L’information nationale"},{"id":"d2","texte":"Le français"}]}]}$ex$::jsonb,
