oir dans la ville.","type":"categories","categories":[{"id":"c0","texte":"Sociale"},{"id":"c1","texte":"Municipale"}],"items":[{"id":"i0","texte":"Obtenir un répit pour payer les loyers"},{"id":"i1","texte":"Faire de Paris une commune qui s’administre elle-même"},{"id":"i2","texte":"Interdire le travail de nuit des boulangers"},{"id":"i3","texte":"Élire le conseil de la ville de Paris"}]},{"enonce":"Quelle conséquence la Commune a-t-elle sur la République naissante ?","aide":"Pense à l’image qu’elle laisse chez les gouvernants.","type":"choix","options":[{"id":"a","texte":"Elle rétablit la monarchie dans toute la France"},{"id":"b","texte":"Elle n’a aucun effet sur la vie politique française"},{"id":"c","texte":"Elle fait aboutir immédiatement toutes les réformes sociales demandées"},{"id":"d","texte":"Elle nourrit la peur du désordre social, qui freine les réformes"}],"multiple":false}]}$ex$::jsonb,
