   $ex${"titre":"Le tocsin d’août 1914","competence":"analyser-document","situation":"Dans un village du Jura, un instituteur socialiste imaginaire, Paul, tient un carnet. Le 2 août 1914, il note ce qu’il voit. Pour comprendre, il confronte ce récit à un tableau des camps politiques.","documents":[{"id":"carnet","type":"texte","genre":"source","titre":"Le carnet de Paul, 2 août 1914","source":"Carnet imaginé pour l’exercice.","blocs":["Jaurès est mort depuis deux jours, tué à Paris dans un café. Il voulait sauver la paix.","La mobilisation est affichée à la mairie. Le syndicaliste de la forge et le curé, qui ne se parlaient plus depuis les inventaires de 1906, sonnent le tocsin ensemble."]},{"id":"camps","type":"tableau","titre":"Les camps politiques avant et en août 1914","source":"Tableau de synthèse d’après le cours.","colonnes":["Camp","Avant 1914","En août 1914"],"lignes":[["Socialistes (SFIO)","Jaurès défend la paix et combat la loi de trois ans","Ils se rallient à l’effort de guerre"],["Catholiques","Ils vivent la séparation et les inventaires comme une blessure","Ils se rallient à l’effort de guerre"],["Action française","Elle conteste le régime républicain","Elle soutient la guerre"]],"enteteLignes":true}],"questions":[{"enonce":"Jaurès est assassiné le 31 juillet 1914. Depuis combien de jours est-il mort quand Paul écrit ?","aide":"Compte du 31 juillet au 2 août.","type":"nombre","unite":"jours"},{"enonce":"Touche la case qui dit ce que Jaurès défendait avant 1914.","aide":"Cherche la ligne des socialistes, colonne « Avant 1914 ».","type":"zone","document":"camps","multiple":false},{"enonce":"Que montre le tocsin sonné par le syndicaliste et le curé ?","aide":"Relie le carnet à la dernière colonne du tableau.","type":"choix","options":[{"id":"a","texte":"L’Union sacrée : des camps rivaux la veille se rassemblent"},{"id":"b","texte":"Le refus de la mobilisation par les ouvriers et les prêtres"},{"id":"c","texte":"La fin de la séparation des Églises et de l’État"},{"id":"d","texte":"La victoire des socialistes sur les catholiques du village"}],"multiple":false},{"enonce":"Range chaque fait : il relève des tensions d’avant 1914 ou de l’union d’août 1914 ?","aide":"Cherche ce qui sépare les Français, puis ce qui les rassemble.","type":"categories","categories":[{"id":"c0","texte":"Tension d’avant 1914"},{"id":"c1","texte":"Union d’août 1914"}],"items":[{"id":"i0","texte":"Le tocsin sonné ensemble"},{"id":"i1","texte":"Les grèves réprimées par Clemenceau"},{"id":"i2","texte":"Le ralliement de la SFIO à l’effort de guerre"},{"id":"i3","texte":"Les inventaires de 1906"}]}]}$ex$::jsonb,
