  ('7f00d200-d0e4-5b8b-940c-9752dbdb4aa7'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Julien, fils de paysan, devenu employé","competence":"analyser-document","situation":"Julien, personnage imaginaire, quitte la ferme familiale pour devenir employé dans un grand magasin parisien. Il écrit à sa sœur Marthe et lui joint des chiffres sur la population de la France et de l’Allemagne.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Lettre de Julien à sa sœur, 1910","source":"Lettre écrite pour l’exercice.","blocs":["Chère Marthe, je suis maintenant employé au rayon des gants. J’ai quitté la ferme, mais papa la garde : il vend son lait et ses œufs, et les droits de douane le protègent de la concurrence étrangère.","Ici, le tramway est électrique et l’usine du faubourg a remplacé ses machines à vapeur. Mais chez nous, dans la plaine, presque tout le monde vit encore de la terre."]},{"id":"pop","type":"graphique","forme":"barres","titre":"La population de la France et de l’Allemagne","source":"Chiffres arrondis, en millions d’habitants.","categories":["France","Allemagne"],"series":[{"nom":"Vers 1870","valeurs":[36,41],"teinte":"bleu"},{"nom":"Vers 1910","valeurs":[40,65],"teinte":"violet"}],"axeY":{"titre":"Habitants","unite":"en millions","min":0,"max":70,"pas":10},"valeurs":true}],"questions":[{"enonce":"Touche le mot qui nomme le nouveau groupe social auquel appartient Julien.","aide":"Il travaille dans un grand magasin, pas à l’usine.","type":"zone","document":"lettre","multiple":false},{"enonce":"Range chaque élément du récit : il change ou il dure ?","aide":"Cherche ce qui est nouveau en 1910, puis ce qui vient d’avant.","type":"categories","categories":[{"id":"c0","texte":"Ce qui change"},{"id":"c1","texte":"Ce qui dure"}],"items":[{"id":"i0","texte":"Une plaine où presque tous vivent de la terre"},{"id":"i1","texte":"Le travail d’employé de grand magasin"},{"id":"i2","texte":"L’exploitation familiale protégée par les tarifs douaniers"},{"id":"i3","texte":"L’électricité dans l’usine du faubourg"}]},{"enonce":"De combien de millions d’habitants la population allemande augmente-t-elle entre 1870 et 1910 ?","aide":"Soustrais les deux barres de l’Allemagne.","type":"nombre","unite":"millions"},{"enonce":"Combien de fois la hausse allemande est-elle plus grande que la hausse française ?","aide":"Calcule d’abord la hausse française : 40 − 36.","type":"nombre","unite":"fois"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m5"]},"explication":"Julien est **employé** : les grands magasins et les bureaux créent un groupe social nouveau."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c0"}},"explication":"**L’électricité** et **l’emploi de bureau** sont des mutations ; **l’exploitation familiale** (tarifs Méline) et la **vie paysanne** sont des permanences."},{"cle":{"type":"nombre","valeur":24,"tolerance":0},"affichage":"24 millions","explication":"65 − 41 = **24 millions** d’habitants en plus en Allemagne."},{"cle":{"type":"nombre","valeur":6,"tolerance":0},"affichage":"6 fois","explication":"La France gagne 4 millions, l’Allemagne 24 : 24 ÷ 4 = **6 fois**. La démographie française est quasi stagnante."}]$ex$::jsonb),
