   $ex${"titre":"Qui résiste au changement ?","competence":"analyser-document","situation":"Un conseiller municipal imaginaire, M. Durand, plaide en 1910 contre le vote des femmes. Léna, élève de 1re, confronte son discours à un graphique de dates et aux résistances de la société.","documents":[{"id":"discours","type":"texte","genre":"article","titre":"Le discours de M. Durand","source":"Discours imaginé pour l’exercice, d’un personnage fictif.","blocs":["Les femmes ont leur place au foyer : l’école et le bureau suffisent à leur ambition. Donner le bulletin de vote serait l’occasion d’une dangereuse dissolution des mœurs.","Je dis aussi que les lois sociales ruinent nos ateliers : il faut y résister."]},{"id":"dates","type":"graphique","forme":"barres-h","titre":"Année du droit de vote des femmes","source":"Dates arrondies d’après le cours (Royaume-Uni : 1918 pour une partie des femmes).","categories":["Finlande","Allemagne","Royaume-Uni","France"],"series":[{"nom":"Année","valeurs":[1906,1918,1918,1944],"teinte":"violet"}],"axeY":{"titre":"Année","min":1900,"max":1950,"pas":10},"valeurs":true}],"questions":[{"enonce":"Touche le pays qui accorde le vote aux femmes le plus tardivement.","aide":"Cherche la plus longue barre.","type":"zone","document":"dates","multiple":false},{"enonce":"Combien d’années la France attend-elle de plus que la Finlande ?","aide":"Soustrais la date de la Finlande à celle de la France.","type":"nombre","unite":"ans"},{"enonce":"Touche le mot qui montre la crainte des élites devant le changement des mœurs.","aide":"Cherche le mot qui annonce une disparition des règles anciennes.","type":"zone","document":"discours","multiple":false},{"enonce":"Associe chaque groupe à ce à quoi il résiste.","aide":"Le discours cite deux de ces résistances : repère-les puis déduis les autres.","type":"association","gauche":[{"id":"g0","texte":"Les élites"},{"id":"g1","texte":"L’Église"},{"id":"g2","texte":"Les campagnes"},{"id":"g3","texte":"Le patronat"}],"dr