  ('5a295ebf-0975-52d0-92e1-27712005a7d3'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Partager l’Afrique : règles et rivalités","competence":"analyser-document","situation":"Lucie prépare une fiche sur la course aux colonies. Elle lit un résumé des règles posées à Berlin puis un tableau des crises entre puissances européennes.","documents":[{"id":"berlin","type":"texte","genre":"source","titre":"La conférence de Berlin, 1884-1885","source":"D’après l’Acte général de la conférence de Berlin (1885), texte adapté.","blocs":["Une puissance qui s’installe sur une côte africaine doit en avertir les autres. Elle doit aussi y maintenir une autorité réelle, capable de faire respecter les droits acquis : une simple déclaration ne suffit plus."]},{"id":"crises","type":"tableau","titre":"Les crises entre puissances","source":"Tableau de synthèse d’après le cours.","colonnes":["Crise","Date","Puissances opposées","Issue"],"lignes":[["Fachoda","1898","France et Royaume-Uni, au Soudan","Recul de la France"],["Première crise marocaine","1905","France et Allemagne","Tension durable"],["Seconde crise marocaine","1911","France et Allemagne","Tension durable"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui montre qu’il faut occuper le territoire pour de bon et non le revendiquer sur le papier.","aide":"Cherche l’adjectif qui qualifie l’autorité à maintenir.","type":"zone","document":"berlin","multiple":false},{"enonce":"Touche la case qui indique le résultat de l’incident de Fachoda pour la France.","aide":"Lis la dernière colonne de la première ligne.","type":"zone","document":"crises","multiple":false},{"enonce":"Combien d’années séparent Fachoda de la seconde crise marocaine ?","aide":"Soustrais les dates de la colonne « Date ».","type":"nombre","unite":"ans"},{"enonce":"Que montrent ces crises à la veille de 1914 ?","aide":"Relis les puissances opposées : ce sont les mêmes que sur le continent européen.","type":"choix","options":[{"id":"a","texte":"Les colonies n’ont aucun lien avec les tensions en Europe"},{"id":"b","texte":"Le Ro