   $ex${"titre":"Le devoir de civiliser, tel qu’on le disait","competence":"analyser-texte","situation":"Nina lit l’un des discours les plus célèbres de la colonisation. Elle doit comprendre l’argument sans le juger rétrospectivement : c’est ainsi qu’il était formulé en 1885.","documents":[{"id":"ferry","type":"texte","genre":"source","titre":"Jules Ferry à la Chambre des députés","source":"Jules Ferry, discours du 28 juillet 1885 (extrait).","blocs":["Je répète qu’il y a pour les races supérieures un droit, parce qu’il y a un devoir pour elles. Elles ont le devoir de civiliser les races inférieures."]}],"questions":[{"enonce":"À quelle famille de motivations l’argument de Ferry se rattache-t-il ?","aide":"Ferry parle d’un devoir de civiliser, pas de commerce ni de bases navales.","type":"choix","options":[{"id":"a","texte":"Fiscale : réduire l’impôt en métropole"},{"id":"b","texte":"Économique : trouver des débouchés"},{"id":"c","texte":"Idéologique : la « mission civilisatrice »"},{"id":"d","texte":"Stratégique : contrôler des routes maritimes"}],"multiple":false},{"enonce":"Complète la phrase avec un mot de l’extrait.","aide":"Relis la deuxième phrase de l’extrait.","type":"trous","segments":["Pour Ferry, les « races supérieures » ont le ",0," de civiliser."],"banque":["hasard","profit","devoir"]},{"enonce":"Associe chaque motivation à un exemple.","aide":"Trois familles : l’argent, la puissance, les idées.","type":"association","gauche":[{"id":"g0","texte":"Économique"},{"id":"g1","texte":"Stratégique"},{"id":"g2","texte":"Idéologique"}],"droite":[{"id":"d0","texte":"La mission civilisatrice"},{"id":"d1","texte":"Des matières premières et des débouchés"},{"id":"d2","texte":"Des bases navales et le prestige après 1871"}]}]}$ex$::jsonb,
