   $ex${"titre":"Un administrateur, trois statuts","competence":"analyser-document","situation":"Un administrateur colonial imaginaire explique son travail à un jeune stagiaire. Maëlle croise ce récit avec un tableau des statuts et réfléchit à la façon dont les colonisés ont pu résister.","documents":[{"id":"adm","type":"texte","genre":"source","titre":"Notes d’un administrateur","source":"Texte écrit pour l’exercice, d’un personnage fictif.","blocs":["Ici, je peux faire punir un homme sans passer devant un juge : c’est le Code de l’indigénat. Il doit aussi demander une autorisation pour quitter son district.","Quelques-uns apprennent le français à l’école de la mission. Ils lisent nos livres, et certains nous opposent déjà nos propres principes."]},{"id":"statuts","type":"tableau","titre":"Colonie, protectorat, Algérie","source":"Tableau d’après le cours.","colonnes":["Statut","Ce qu’il implique"],"lignes":[["Colonie","Administration directe"],["Protectorat","Le souverain local est maintenu, sous tutelle"],["Algérie","Des départements français"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui montre que l’indigénat écarte la justice ordinaire.","aide":"Cherche la personne que l’on ne rencontre pas avant d’être puni.","type":"zone","document":"adm","multiple":false},{"enonce":"Touche la case du statut où le souverain local reste en place.","aide":"Ce statut garde un souverain, mais sous tutelle.","type":"zone","document":"statuts","multiple":false},{"enonce":"Range chaque fait : résistance directe ou appropriation des outils du colonisateur ?","aide":"Trois gestes s’opposent frontalement ; un s’appuie sur ce qu’on a appris à l’école.","type":"categories","categories":[{"id":"c0","texte":"Résistance directe"},{"id":"c1","texte":"Appropriation des outils"}],"items":[{"id":"i0","texte":"Réclamer l’égalité au nom des principes français"},{"id":"i1","texte":"Une désertion"},{"id":"i2","texte":"Une révolte armée"},{"id":"i3","texte":"Le refus de l’impôt"}