   $ex${"titre":"Une lettre au gouverneur","competence":"analyser-document","situation":"En 1912, un jeune lettré colonisé imaginaire, formé à l’école française, écrit au gouverneur. Anaïs confronte sa lettre au schéma de la société coloniale.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Lettre d’un lettré au gouverneur, 1912","source":"Lettre écrite pour l’exercice, d’un personnage fictif.","blocs":["Monsieur le gouverneur, votre école m’a appris la liberté et l’égalité proclamées en 1789.","Je sers l’administration comme interprète, mais je reste un sujet, sans droit de vote. Appliquez-nous ces principes."]},{"id":"schema","type":"schema","titre":"La société coloniale","source":"Schéma d’après le cours.","largeur":320,"hauteur":230,"elements":[{"forme":"rect","x":70,"y":20,"l":180,"h":44,"arrondi":8,"teinte":"ambre","motif":"clair","texte":"Minorité européenne","id":"z1","zone":true},{"forme":"ligne","de":[160,64],"a":[160,86],"fleche":"fin"},{"forme":"rect","x":40,"y":88,"l":240,"h":44,"arrondi":8,"teinte":"violet","motif":"clair","texte":"Intermédiaires locaux","id":"z2","zone":true},{"forme":"ligne","de":[160,132],"a":[160,154],"fleche":"fin"},{"forme":"rect","x":20,"y":156,"l":280,"h":44,"arrondi":8,"teinte":"vert","motif":"clair","texte":"Majorité colonisée","id":"z3","zone":true},{"forme":"texte","x":160,"y":218,"texte":"Postes et revenus en haut, école rare en bas","taille":"petit","italique":true,"ancre":"milieu"}]}],"questions":[{"enonce":"Touche le groupe composé de chefs, d’interprètes et de tirailleurs qui servent l’administration.","aide":"Ce groupe est au milieu du schéma.","type":"zone","document":"schema","multiple":false},{"enonce":"Touche le principe de 1789 que l’auteur de la lettre réclame pour lui-même.","aide":"Il l’associe à la liberté dans la première phrase.","type":"zone","document":"lettre","multiple":false},{"enonce":"À quel groupe du schéma appartient l’auteur de la lettre ?","aide":"Il dit qu’il sert l’administration comme interprète.","type":"choix","options":[{"id":"a","texte":"Aux intermédiaires locaux"},{"id":"b","texte":"À la majorité colonisée sans école"},{"id":"c","texte":"À la minorité européenne"},{"id":"d","texte":"À l’administration métropolitaine"}],"multiple":false},{"enonce":"Range ces étapes pour expliquer comment l’école coloniale nourrit les revendications.","aide":"Pars de l’école, finis par les mouvements du XXe siècle.","type":"ordre","items":[{"id":"a","texte":"Un petit nombre d’enfants apprennent le français"},{"id":"b","texte":"Ils réclament l’égalité"},{"id":"c","texte":"Le colonisateur ouvre une école pour former des auxiliaires"},{"id":"d","texte":"Les mouvements nationalistes du XXe siècle reprennent ces revendications"},{"id":"e","texte":"Ils découvrent les principes de 1789"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"Ce sont les **intermédiaires locaux** : chefs, interprètes, tirailleurs."},{"cle":{"type":"zone","ids":["m12"]},"explication":"Il réclame l’**égalité** : le colonisateur a formé ceux qui lui opposent ses propres principes."},{"cle":{"type":"choix","ids":["a"]},"explication":"Interprète au service de l’administration, il est un **intermédiaire local**, mais reste un sujet sans vote."},{"cle":{"type":"ordre","ids":["c","a","e","b","d"]},"explication":"De l’**école** aux **revendications d’égalité**, puis aux **mouvements nationalistes** : le colonisateur a formé, sans le vouloir, ceux qui lui opposeront ses principes."}]$ex$::jsonb),
