   $ex${"titre":"Lettre d’un soldat en 1917","competence":"analyser-document","situation":"Un soldat imaginaire, Étienne, écrit à sa mère depuis un secteur calme du front en 1917. Camille croise sa lettre avec un tableau sur « l’année de la crise » et sur les trois phases de la guerre.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Lettre d’Étienne à sa mère, 1917","source":"Lettre écrite pour l’exercice, d’un personnage fictif.","blocs":["Chère maman, nous creusons et refaisons la même tranchée depuis des mois. Le front ne bouge presque plus, mais les obus continuent d’emporter nos camarades.","On dit que les Américains arrivent et que, en Russie, tout bascule. Dans certains régiments, des hommes refusent de remonter à l’attaque."]},{"id":"crise","type":"tableau","titre":"1917, l’année de la crise","source":"Tableau d’après le cours.","colonnes":["Événement","Sa portée"],"lignes":[["Les mutineries françaises","Le consentement s’use"],["Les révolutions russes","Un allié va sortir de la guerre"],["L’entrée en guerre des États-Unis (avril)","La balance bascule à terme"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui montre que la guerre est devenue une guerre de position.","aide":"Cherche l’ouvrage que les soldats refont sans cesse.","type":"zone","document":"lettre","multiple":false},{"enonce":"Range chaque fait : guerre de mouvement ou guerre de position ?","aide":"Le mouvement, c’est 1914 et 1918 ; la position, c’est entre les deux.","type":"categories","categories":[{"id":"c0","texte":"Guerre de mouvement"},{"id":"c1","texte":"Guerre de position"}],"items":[{"id":"i0","texte":"Les tranchées et l’artillerie massive"},{"id":"i1","texte":"La bataille de la Marne (1914)"},{"id":"i2","texte":"Verdun (1916)"},{"id":"i3","texte":"Les offensives allemandes du printemps 1918"}]},{"enonce":"Associe chaque événement de 1917 à sa portée.","aide":"Relis le tableau, colonne par colonne.","type":"association","gauche":[{"id":"g0","texte":"Les mutineries françaises"},{"id":"g1","texte":"Les révolutions russes"},{"id":"g2","texte":"L’entrée des États-Unis"}],"droite":[{"id":"d0","texte":"La balance bascule à terme"},{"id":"d1","texte":"Le consentement s’use"},{"id":"d2","texte":"Un allié va sortir de la guerre"}]},{"enonce":"Que dit la lettre d’Étienne du « front qui ne bouge plus » ?","aide":"Relis la première phrase de la lettre.","type":"choix","options":[{"id":"a","texte":"La guerre se gagne uniquement par de grandes avances"},{"id":"b","texte":"La guerre ne tue plus car les armées restent immobiles"},{"id":"c","texte":"La guerre est finie dans son secteur depuis plusieurs mois"},{"id":"d","texte":"La guerre continue de consommer des hommes à la place des kilomètres"}],"multiple":false}]}$ex$::jsonb,
