   $ex${"titre":"Vivre sous l’occupation, subir le génocide","competence":"analyser-document","situation":"Une habitante imaginaire d’un village du nord de la France occupé raconte sa vie en 1916. Inès confronte son récit à un tableau sur les violences contre les civils.","documents":[{"id":"recit","type":"texte","genre":"lettre","titre":"Journal d’Alice, village du Nord occupé, 1916","source":"Journal écrit pour l’exercice, d’un personnage fictif.","blocs":["Les soldats allemands logent chez nous. Ils prennent le blé, les chevaux et le charbon : ce sont des réquisitions permanentes, et nous manquons de pain.","Nous n’avons aucune nouvelle de mon mari, qui est resté de l’autre côté du front."]},{"id":"violences","type":"tableau","titre":"Les civils victimes de la guerre","source":"Tableau d’après le cours.","colonnes":["Violence","Où"],"lignes":[["Occupation et réquisitions","Le nord de la France, la Belgique"],["Bombardements, famines","Partout"],["Déplacements de populations","Fronts de l’Est et des Balkans"],["Génocide des Arméniens (1915-1916)","Empire ottoman"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui désigne les prélèvements imposés à la population par l’armée d’occupation.","aide":"Ils portent sur le blé, les chevaux et le charbon.","type":"zone","document":"recit","multiple":false},{"enonce":"Touche la ligne du tableau qui correspond au récit d’Alice.","aide":"Cherche l’occupation et les réquisitions.","type":"zone","document":"violences","multiple":false},{"enonce":"Associe chaque violence à sa zone.","aide":"Utilise la colonne « Où » du tableau.","type":"association","gauche":[{"id":"g0","texte":"Occupation et réquisitions"},{"id":"g1","texte":"Déplacements de populations"},{"id":"g2","texte":"Génocide des Arméniens"}],"droite":[{"id":"d0","texte":"Fronts de l’Est et des Balkans"},{"id":"d1","texte":"Empire ottoman"},{"id":"d2","texte":"Nord de la France et Belgique"}]},{"enonce":"Pourquoi le génocide des Arméniens est-il présenté c